import { execFileSync } from 'node:child_process';
import { vi } from 'vitest';

// Temporary diagnostic: run the approved assertion against the actual baseline adapter.
vi.mock('esbuild', async (importOriginal) => {
  const original = await importOriginal<typeof import('esbuild')>();
  return {
    ...original,
    build: (options: import('esbuild').BuildOptions) =>
      original.build({
        ...options,
        plugins: [
          ...(options.plugins ?? []),
          {
            name: 'baseline-owned-command',
            setup(builder) {
              builder.onLoad({ filter: /[/\\]owned-command\.ts$/ }, () => ({
                loader: 'ts',
                contents: execFileSync(
                  'git',
                  ['show', '630ce380787f446e803f94b4b90cbbdbf8663364:platform/process/owned-command.ts'],
                  { encoding: 'utf8', windowsHide: true },
                ),
              }));
            },
          },
        ],
      }),
  };
});

await import('./owned-command-termination.test.js');
